"""
Static configuration for the Línea 1 plant-view Streamlit app.

Reproduces the Grafana "Producción - Línea 1" canvas panel
(grafana/dashboard_linea1.json) as a Streamlit page: the same 3D plant
layout image with live production/scrap values overlaid near each machine
group, built from the same LINE1_*_SHIFT derived rollup timeseries
hourly_production_report already writes -- no new backend needed.

Positions below are approximate (eyeballed against the image, not a
pixel-exact port of Grafana's own canvas coordinates -- that canvas's
declared coordinate space, 1200x688, doesn't match this image's native
resolution 1684x966, and a couple of its element positions actually sit
outside its own declared bounds). Tune ELEMENTS' x/y if a label ends up in
an awkward spot once you see it rendered.
"""
from datetime import date, datetime, timedelta, timezone

LOCAL_TZ = timezone(timedelta(hours=-4))

LOGO_B64 = """"""  # Empresas Polar logo, embedded as base64

# Plant layout diagram (Línea 1) -- same image used in the Grafana canvas panel,
# re-encoded as JPEG (was a 1.57MB PNG with no real transparency) and embedded as
# base64, same reasoning as the logo: Fusion's Streamlit editor has no binary-asset upload.
PLANT_IMAGE_B64 = ""

# x/y are in the SAME data-coordinate space main.py's x/y axes use (image
# spans data x:[0,1] y:[0,1], y=0 at the image's own bottom edge, y=1 at its
# top -- main.py flips these image-relative fractions with `1 - el["y"]` so
# 0 still means "top of image" here). Stays within the image bounds --
# Printer and ISpray have visible black space around their boxes there
# already. MINSTER and D&I now render BELOW the image instead (data y < 0,
# in the margin PLOT_Y_MIN adds), since there's no clear space inside the
# image itself near either without overlapping machine graphics or the
# "D & I"/"LAVADORA" text baked into the photo -- see MINSTER_X/Y and
# DI_ROW_Y below.
#
# NOTE: these y fractions are relative to PLANT_IMAGE_B64's own height, which
# was cropped from 966px to PLANT_IMAGE_HEIGHT=851px (removed ~134px of pure
# black padding baked into the bottom of the original photo, below all the
# actual machine graphics/text -- that dead space was most of what made the
# below-image boxes look like they had "too much space" above them, no
# matter how far up PLOT_Y_MIN/DI_ROW_Y/MINSTER_Y moved them). If
# PLANT_IMAGE_B64 is ever re-cropped or swapped, these three y values need
# rescaling by (old_image_height / new_image_height) to land on the same
# physical spot in the photo.
ELEMENTS = [
    {"label": "Producción", "kind": "production", "target": "LINE1_PRINTER_PRODUCTION_SHIFT", "x": 0.819, "y": 0.3503},
    {"label": "Merma", "kind": "scrap", "target": "LINE1_PRINTER_SCRAP_SHIFT", "x": 0.819, "y": 0.4411},
    {"label": "Producción", "kind": "production", "target": "LINE1_ISPRAY_PRODUCTION_SHIFT", "x": 0.26, "y": 0.1116},
]

# Native dimensions of the (cropped) PLANT_IMAGE_B64 -- main.py derives its
# y-axis scaleratio from these so the image never renders distorted.
PLANT_IMAGE_WIDTH = 1684
PLANT_IMAGE_HEIGHT = 851

# Fixed pixel size for every overlay box (same for Producción/Merma, per
# explicit request -- also removes any font-metric-dependent auto-sizing
# variance between environments, which is why earlier positions that looked
# clear in a local static render still overlapped once deployed to Fusion's
# actual browser rendering).
ELEMENT_WIDTH = 115
ELEMENT_HEIGHT = 46

# MINSTER moved out of the image (see ELEMENTS' comment above) into the
# below-image margin, left-aligned under the "MINSTER" text baked into the
# plant image. Direct render coordinates (data space), not image-relative
# fractions -- no y-flip applied in main.py, unlike ELEMENTS above.
MINSTER_TARGET = "LINE1_MINSTER_PRODUCTION_SHIFT"
MINSTER_X = 0.115  # nudged right to center under the "MINSTER" text
MINSTER_Y = -0.035  # image crop removed most of the gap; this is now a small intentional buffer

# D&I has no line-level rollup timeseries per physical machine (only the
# combined LINE1_DI_PRODUCTION_SHIFT/_SCRAP_SHIFT), so its per-machine
# numbers are computed live from Production Report events (see
# cdf_service.load_di_machine_values) rather than read from a target here.
# Per customer request: one column per D&I machine, laid out in a row
# matching the physical machines on Línea 1 (functions/hourly_production_
# report/config.py MACHINE_CONFIGS "di" codes), each column stacking three
# numbers with no text labels -- machine number on top, Producción in the
# middle, Merma at the bottom, in the below-image margin (see MINSTER's
# comment above; DI_ROW_Y values are direct render coordinates, not
# image-relative fractions). DI_COLUMN_X positions are a first pass (evenly
# spaced across the D&I row); expect to fine-tune once seen live.
DI_MACHINE_CODES = ["DI11", "DI12", "DI14", "DI15", "DI17", "DI18"]
DI_COLUMN_X = [0.30, 0.42, 0.54, 0.66, 0.78, 0.90]
DI_ROW_Y = {"number": -0.002, "production": -0.05, "scrap": -0.115}  # scrap moved down -- at -0.09 it was only ~1-2px from touching the production box above it (both 30px tall, 0.04 gap barely exceeded their combined half-heights)
DI_NUMBER_BOX_WIDTH = 46
DI_NUMBER_BOX_HEIGHT = 28
# Producción/Merma can run up to 8 digits with thousands separators (e.g.
# "12,345,678"), so these need to be much wider than the 2-digit
# machine-number box above them.
DI_VALUE_BOX_WIDTH = 100
DI_VALUE_BOX_HEIGHT = 30

# The image occupies data y:[0,1] (unchanged, native proportions). This
# extends the y-axis range below 0 to add a plain black margin underneath
# it for MINSTER + the D&I rows, since their old positions (inside the
# image, near its bottom edge) collided with the "D & I"/"LAVADORA" text
# and machine graphics baked into the photo itself. main.py scales its
# figure `height` by the same (1 - PLOT_Y_MIN) factor so the image renders
# at its original pixel size instead of Plotly shrinking it to fit the
# taller axis range.
PLOT_Y_MIN = -0.16
BASE_FIGURE_HEIGHT = 650

# Matches the Grafana canvas panel exactly (grafana/dashboard_linea1.json):
# production elements use super-light-blue/dark-blue, scrap elements use
# super-light-red/dark-red.
ELEMENT_COLORS = {
    "production": {"bg": "#dbeafe", "border": "#1e40af"},
    "scrap": {"bg": "#fee2e2", "border": "#991b1b"},
    "neutral": {"bg": "#f3f4f6", "border": "#4b5563"},
}

